mapper.select:
SELECT

FROM `person` p
LEFT JOIN `organization` o ON p.org_id = o.id AND o.deleted = 0
WHERE p.deleted = 0

    AND p.org_id = #{query.orgId}


    AND p.person_type = #{query.personType}


    AND p.person_name LIKE CONCAT('%', #{query.personName}, '%')


    AND p.phone LIKE CONCAT('%', #{query.phone}, '%')


    AND p.status = #{query.status}

ORDER BY p.create_time DESC

    LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT COUNT(*)
FROM `person` p
WHERE p.deleted = 0

    AND p.org_id = #{query.orgId}


    AND p.person_type = #{query.personType}


    AND p.person_name LIKE CONCAT('%', #{query.personName}, '%')


    AND p.phone LIKE CONCAT('%', #{query.phone}, '%')


    AND p.status = #{query.status}

